/* Honor points are a secondary feature: errors never block reading, uploads or the home page. */
const pointsKinds = {read:'有效阅读',upload:'新资料入库',note:'首次发布笔记',adjust:'人工调整'};
const PointsRequest = {
  props:{request:{type:Function,required:true},currentUser:{type:Object,default:()=>({})}},
  data(){return {pointsGeneration:0,pointsDisposed:false,pointsIdentity:localStorage.getItem('accessToken')};},
  beforeUnmount(){this.pointsDisposed=true;this.pointsGeneration++;},
  methods:{
    async pointsAPI(path,options={}){
      const identity=localStorage.getItem('accessToken');
      if(this.pointsDisposed||identity!==this.pointsIdentity)throw Error('账号或页面已变更，请重新打开积分页面。');
      const response=await this.request(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});
      const data=await response.json().catch(()=>({}));
      if(this.pointsDisposed||identity!==localStorage.getItem('accessToken'))throw Error('账号或页面已变更，请重新打开积分页面。');
      if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'请求未完成，请检查输入或稍后重试。');
      return data;
    },
    pointsTime(value){return value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—';},
    pointsKind(kind){return pointsKinds[kind]||kind;},
    pointsDelta(value){return value>0?'+'+value:String(value);},
  },
};

const PointsHomeCard={
  mixins:[PointsRequest],emits:['open','action'],data(){return {points:null,unavailable:false,busy:false,refreshClock:null};},
  async mounted(){await this.reload();if(!this.pointsDisposed)this.refreshClock=setInterval(()=>{if(!document.hidden)this.reload();},15000);},
  beforeUnmount(){clearInterval(this.refreshClock);},
  methods:{async reload(){if(this.busy||this.pointsDisposed)return;this.busy=true;try{const result=await this.pointsAPI('/points/me');if(!this.pointsDisposed){this.points=result;this.unavailable=false;}}catch{if(!this.pointsDisposed)this.unavailable=true;}finally{this.busy=false;}}},
  template:`<section class="points-home-card" aria-label="我的积分" :aria-busy="busy">
    <div class="points-home-main"><div><h3><i class="fa-solid fa-medal" aria-hidden="true"></i> 我的积分</h3><p>记录阅读与贡献，当前知识库阅读、资料入库和笔记发布参与计分。</p></div><div v-if="points" class="points-home-score"><strong>{{points.total}}</strong><span>L{{points.level.number}} · {{points.level.name}}<small>今日 {{points.today}} 分 · 本月 {{points.month}} 分</small></span></div></div>
    <p v-if="unavailable" class="points-home-status" role="status">{{points?'刷新失败，显示上次积分。':'积分暂不可用，仍可正常阅读和上传。'}}<button type="button" :disabled="busy" @click="reload">重试积分</button></p><p v-else-if="!points" class="points-home-status" role="status">正在读取积分…</p>
    <p v-if="points && (points.excluded || points.policy?.enabled===false)" class="points-home-status" role="status">当前账号的积分奖励已暂停，知识库仍可正常使用。</p>
    <nav class="points-action-links" aria-label="积分与知识库操作"><button type="button" @click="$emit('action','read')">去阅读资料</button><button type="button" @click="$emit('action','upload')">上传资料</button><button type="button" @click="$emit('open')">查看积分 <i class="fa-solid fa-angle-right" aria-hidden="true"></i></button></nav>
  </section>`,
};

const PointsCenter={
  mixins:[PointsRequest],
  emits:['action'],
  data(){return {tab:'overview',summary:null,error:'',busy:false,rows:[],activity:[],total:0,page:1,kind:'',range:[],period:'month',board:null,rules:null,refreshClock:null,requestSerial:0};},
  computed:{
    progress(){if(!this.summary?.level.next)return 100;const level=this.summary.level;return Math.min(100,Math.max(0,100*(this.summary.total-level.threshold)/(level.next.threshold-level.threshold)));},
    pages(){return Math.max(1,Math.ceil(this.total/20));},
    tasks(){if(!this.summary)return [];return ['read','upload','note'].map(kind=>({kind,label:pointsKinds[kind],done:this.summary.earned[kind],limit:this.summary.policy[kind+'_limit'],points:this.summary.policy[kind+'_points']}));},
  },
  mounted(){this.reload();this.refreshClock=setInterval(()=>{if(!document.hidden&&!this.busy&&this.tab==='overview')this.reload();},15000);},
  beforeUnmount(){clearInterval(this.refreshClock);this.requestSerial++;},
  methods:{
    async reload(){
      const serial=++this.requestSerial;this.busy=true;this.error='';
      try{
        const summary=await this.pointsAPI('/points/me');if(serial!==this.requestSerial)return;this.summary=summary;
        if(this.tab==='overview'||this.tab==='ledger'){
          const params=new URLSearchParams({page:this.tab==='overview'?1:this.page,page_size:this.tab==='overview'?5:20,kind:this.tab==='overview'?'':this.kind});
          if(this.tab==='ledger'&&this.range?.length===2){params.set('start',this.range[0]);params.set('end',this.range[1]);}
          const result=await this.pointsAPI('/points/ledger?'+params);if(serial!==this.requestSerial)return;this.rows=result.items;this.total=result.total;
          if(this.tab==='overview'){const activity=await this.pointsAPI('/points/activity');if(serial!==this.requestSerial)return;this.activity=activity.items;}
        }else if(this.tab==='leaderboard'){
          const result=await this.pointsAPI('/points/leaderboard?'+new URLSearchParams({period:this.period,page:this.page,page_size:20}));if(serial!==this.requestSerial)return;this.board=result;this.total=result.total;
        }else{const result=await this.pointsAPI('/points/rules');if(serial!==this.requestSerial)return;this.rules=result;}
      }catch(error){if(serial===this.requestSerial&&!this.pointsDisposed)this.error=error.message;}
      finally{if(serial===this.requestSerial)this.busy=false;}
    },
    changeTab(){this.page=1;this.rows=[];this.board=null;this.total=0;this.reload();},
    filter(){this.page=1;this.reload();},
  },
  template:`<section class="points-center" aria-label="我的积分">
    <header class="points-heading"><div><h2>积分中心</h2><p>记录参与与贡献。当前知识库阅读、资料入库和笔记发布可获积分，尽调任务暂不计分。</p></div><el-button @click="reload" :loading="busy">刷新</el-button></header>
    <p v-if="busy" class="points-loading" role="status" aria-live="polite"><i class="fa-solid fa-circle-notch fa-spin" aria-hidden="true"></i>正在读取积分页面，请稍候…</p><div v-if="error" class="points-error" role="alert">{{error}} <el-button link @click="reload">重试</el-button></div>
    <template v-if="summary">
      <p v-if="!summary.policy.enabled||summary.excluded" class="points-notice" role="status">{{summary.excluded?'该账号已暂停参与积分，历史积分保留。':'积分奖励已暂停，资料阅读和上传仍可正常使用。'}}</p>
      <div class="points-summary"><div><span>累计荣誉积分</span><strong>{{summary.total}}</strong><b>L{{summary.level.number}} · {{summary.level.name}}</b></div><dl><div><dt>本月获得</dt><dd>{{summary.month}}</dd></div><div><dt>今日获得</dt><dd>{{summary.today}}</dd></div><div><dt>本月排名</dt><dd>{{summary.rank?.rank||'—'}}</dd></div></dl></div>
      <div class="points-level"><span>{{summary.level.next?'距下一等级「'+summary.level.next.name+'」还差 '+Math.max(0,summary.level.next.threshold-summary.total)+' 分':'已达到当前最高等级'}}</span><el-progress :percentage="progress" :show-text="false" :stroke-width="7"></el-progress></div>
      <el-tabs v-model="tab" @tab-change="changeTab">
        <el-tab-pane label="积分概览" name="overview"><h3>今日奖励进度</h3><p class="points-help">按已使用奖励次数展示，撤回不释放当日额度；无需刻意完成。</p><div class="points-task" v-for="task in tasks" :key="task.kind"><div><strong>{{task.label}}</strong><small>已计 {{task.done}} / {{task.limit}} 次 · 每次 {{task.points}} 分</small></div><div class="points-task-action"><span>{{task.done*task.points}} / {{task.limit*task.points}} 分</span><button type="button" @click="$emit('action',task.kind)">{{task.kind==='read'?'去阅读':task.kind==='upload'?'去上传':'去写笔记'}}</button></div></div><h3 class="points-section-title">最近入账记录</h3></el-tab-pane>
        <el-tab-pane label="积分明细" name="ledger"><div class="points-toolbar"><el-select v-model="kind" aria-label="积分类型" @change="filter"><el-option label="全部类型" value=""></el-option><el-option v-for="(label,value) in {read:'阅读',upload:'上传',note:'笔记',adjust:'调整'}" :label="label" :value="value" :key="value"></el-option></el-select><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="积分业务日期范围" @change="filter"></el-date-picker></div></el-tab-pane>
        <el-tab-pane label="排行榜" name="leaderboard"><div class="points-toolbar"><el-select v-model="period" aria-label="榜单周期" @change="filter"><el-option label="本月榜" value="month"></el-option><el-option label="本周榜" value="week"></el-option><el-option label="累计榜" value="all"></el-option></el-select><span class="points-help">同分并列 · 管理员及排除账号不参榜 · 仅显示汇总积分</span></div><p v-if="board&&!board.enabled" role="status">排行榜当前未开放。</p><p v-if="board?.enabled" class="points-notice">{{board.me?'我的排名：'+board.me.rank+' · 本周期 '+board.me.score+' 分':'当前未参榜或本周期暂无有效积分。'}}</p><div class="points-table-wrap" v-if="board?.enabled"><table class="points-table"><thead><tr><th>排名</th><th>账号</th><th>等级</th><th>阅读</th><th>贡献</th><th>积分</th></tr></thead><tbody><tr v-for="row in board.items" :key="row.user_id" :class="{'points-is-me':row.username===currentUser.username}"><td>{{row.rank}}</td><td>{{row.username}}<small v-if="row.username===currentUser.username">（我）</small></td><td>L{{row.level.number}} · {{row.level.name}}</td><td>{{row.reading}}</td><td>{{row.contribution}}</td><td>{{row.score}}</td></tr><tr v-if="!board.items.length&&!busy&&!error"><td colspan="6">本周期暂无积分记录。</td></tr></tbody></table></div></el-tab-pane>
        <el-tab-pane label="积分规则" name="rules"><template v-if="rules"><p class="points-help">规则 v{{rules.current.version}} · {{pointsTime(rules.current.effective_at)}} 生效 · 北京时间</p><ul class="points-rule-list"><li>有效阅读他人的内部共享资料，每份 +{{rules.current.policy.read_points}} 分，每天最多 {{rules.current.policy.read_limit}} 份；前台累计阅读达到 {{rules.current.policy.read_seconds}} 秒且有阅读交互。</li><li>上传新资料并完成索引后，奖励实际上传人；管理员代上传也记给管理员，不受资料保密等级和授权范围限制。每份 +{{rules.current.policy.upload_points}} 分，每天最多 {{rules.current.policy.upload_limit}} 份。</li><li>新笔记首次发布并完成索引，每篇 +{{rules.current.policy.note_points}} 分，每天最多 {{rules.current.policy.note_limit}} 篇。</li><li>重复上传、后续版本、重试、补传、移动、删除恢复不重复奖励。笔记和生成文件只奖励一次。</li><li>阅读与笔记奖励仍限内部共享文本资料，音视频暂不参与自动奖励；上传奖励不受访问权限限制。积分不扩大资料阅读、下载或管理权限。</li><li>正常整理不扣分。误发积分以独立纠正记录撤回，保留原奖励及原因。</li><li>荣誉积分不兑换、不转让，不改变资料权限，不作为专业资质或绩效结论。</li></ul><h3>等级门槛</h3><div class="points-levels"><span v-for="(item,index) in rules.current.policy.levels" :key="item.threshold">L{{index+1}} {{item.name}} · {{item.threshold}} 分</span></div><div v-for="rule in rules.upcoming" :key="rule.version" class="points-notice">已安排规则 v{{rule.version}}，{{pointsTime(rule.effective_at)}} 生效：{{rule.reason}}</div></template></el-tab-pane>
      </el-tabs>
      <template v-if="tab==='overview'||tab==='ledger'"><div class="points-entry" v-for="row in rows" :key="row.id"><div><strong>{{row.title||pointsKind(row.kind)}}</strong><small>{{pointsTime(row.created_at)}} · {{pointsKind(row.kind)}} · {{row.reason}}</small><small>业务日期 {{row.business_day}} · 规则 v{{row.rule_id}}<template v-if="row.original_id"> · 撤回原奖励</template></small></div><b :class="{'points-negative':row.amount<0}">{{pointsDelta(row.amount)}}</b></div><p v-if="!rows.length&&!busy&&!error" class="points-empty">暂无积分记录，从阅读与贡献资料开始。</p></template><template v-if="tab==='overview'&&activity.length"><h3 class="points-section-title">处理进度与未获奖励记录</h3><div class="points-entry" v-for="(row,index) in activity" :key="index"><div><strong>{{row.title||pointsKind(row.kind)}}</strong><small>{{row.reason}}</small></div><span>{{row.status==='ignored'?'未获奖励':row.expected?'预计 +'+row.expected:'待判断'}}</span></div></template>
      <div v-if="tab==='ledger'||tab==='leaderboard'" class="points-pagination"><el-pagination layout="prev, pager, next, total" :total="total" :page-size="20" v-model:current-page="page" @current-change="reload"></el-pagination></div>
    </template>
  </section>`,
};

const PointsAdmin={
  mixins:[PointsRequest],
  data(){return {tab:'users',busy:false,error:'',message:'',users:[],rows:[],events:[],total:0,page:1,query:'',userFilter:null,eventStatus:'failed',rules:null,policy:null,reason:'',immediatePause:false,saving:false,adjustOpen:false,adjustUser:null,adjustForm:{amount:10,reason:'',original_id:''},adjustRequestId:'',adjustError:'',pendingAdjustment:null};},
  mounted(){this.load();},
  methods:{
    async load(){const serial=++this.pointsGeneration;this.busy=true;this.error='';try{
      if(this.tab==='rules'){const data=await this.pointsAPI('/admin/points/rules');if(serial!==this.pointsGeneration)return;this.rules=data;this.policy=JSON.parse(JSON.stringify(data.history.find(row=>!row.cancelled_at)?.policy||data.current.policy));}
      else{const params=new URLSearchParams({page:this.page,page_size:20});if(this.tab==='users')params.set('q',this.query);if(this.tab==='ledger'&&this.userFilter)params.set('user_id',this.userFilter);if(this.tab==='events')params.set('status',this.eventStatus);const result=await this.pointsAPI('/admin/points/'+this.tab+'?'+params);if(serial!==this.pointsGeneration)return;this[this.tab==='ledger'?'rows':this.tab]=result.items;this.total=result.total;}
    }catch(error){if(serial===this.pointsGeneration)this.error=error.message;}finally{if(serial===this.pointsGeneration)this.busy=false;}},
    change(){this.page=1;this.total=0;this.load();},
    async saveRules(){if(this.saving)return;this.saving=true;this.error='';try{const row=await this.pointsAPI('/admin/points/rules',{method:'PUT',body:JSON.stringify({expected_version:this.rules.latest_version,policy:this.policy,reason:this.reason,immediate_pause:this.immediatePause})});this.reason='';this.immediatePause=false;this.message='规则 v'+row.version+' 将于 '+this.pointsTime(row.effective_at)+' 生效。';await this.load();}catch(error){this.error=error.message;}finally{this.saving=false;}},
    async participation(row){try{const result=await ElementPlus.ElMessageBox.prompt('请填写'+(row.excluded?'恢复':'暂停')+'参与积分的原因，历史积分保留。','参与设置',{inputValidator:v=>!!v&&v.trim().length>=2,confirmButtonText:'保存',cancelButtonText:'取消'});await this.pointsAPI('/admin/points/users/'+row.user_id+'/participation',{method:'PATCH',body:JSON.stringify({excluded:!row.excluded,reason:result.value})});await this.load();}catch(error){if(error instanceof Error)this.error=error.message;}},
    openAdjustment(row,entry=null){this.adjustUser=row;this.adjustForm={amount:entry?-entry.amount:10,reason:'',original_id:entry?.id||''};this.adjustRequestId=crypto.randomUUID().replaceAll('-','');this.adjustError='';this.pendingAdjustment=null;this.adjustOpen=true;},
    async saveAdjustment(){if(this.saving||!this.adjustUser)return;this.saving=true;this.adjustError='';try{
      const serialized=JSON.stringify({...this.adjustForm,request_id:this.adjustRequestId});
      if(this.pendingAdjustment&&this.pendingAdjustment!==serialized)throw Error('重试时请保持原调整内容；如需另一笔调整，请关闭后重新打开。');
      const result=await ElementPlus.ElMessageBox.prompt('请输入当前管理员密码，本次调整将保留永久流水。','验证积分调整',{inputType:'password',inputValidator:v=>!!v,confirmButtonText:'验证并记账',cancelButtonText:'取消',closeOnClickModal:false});
      const confirmation=await this.pointsAPI('/auth/confirm-admin',{method:'POST',body:JSON.stringify({password:result.value,action:'points_adjust',target_user_id:this.adjustUser.user_id})});
      this.pendingAdjustment=serialized;
      const data=await this.pointsAPI('/admin/points/users/'+this.adjustUser.user_id+'/adjustments',{method:'POST',headers:{'X-Admin-Confirmation':confirmation.confirmation_token},body:serialized});
      this.adjustOpen=false;this.message=data.message;await this.load();
    }catch(error){if(error instanceof Error)this.adjustError=error.message;}finally{this.saving=false;}},
    async retry(row){try{await this.pointsAPI('/admin/points/events/'+encodeURIComponent(row.id)+'/retry',{method:'POST',body:'{}'});this.message='已安排重试，同一奖励不会重复发放。';await this.load();}catch(error){this.error=error.message;}},
    viewLedger(row){this.userFilter=row.user_id;this.tab='ledger';this.change();},
  },
  template:`<section class="points-center points-admin" aria-label="积分管理"><header class="points-heading"><div><h2>积分管理</h2><p>独立账本、规则版本及纠正记录。管理员默认不参加员工榜单。</p></div><el-button @click="load" :loading="busy">刷新</el-button></header><p v-if="busy" class="points-loading" role="status" aria-live="polite"><i class="fa-solid fa-circle-notch fa-spin" aria-hidden="true"></i>正在读取积分管理数据，请稍候…</p><p v-if="error" class="points-error" role="alert">{{error}}</p><p v-if="message" class="points-notice" role="status">{{message}}</p>
    <el-tabs v-model="tab" @tab-change="change"><el-tab-pane label="人员积分" name="users"><form class="points-toolbar" @submit.prevent="change"><el-input v-model="query" placeholder="搜索账号" aria-label="积分账号搜索" maxlength="100"></el-input><el-button native-type="submit">查询</el-button></form><div class="points-table-wrap"><table class="points-table"><thead><tr><th>账号</th><th>积分</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in users" :key="row.user_id"><td>{{row.username}}<small>{{row.role==='admin'?'管理员':'普通账号'}}</small></td><td>{{row.total}}</td><td>{{!row.active?'停用或归档':row.excluded?'暂停参与':'正常参与'}}</td><td><el-button link @click="viewLedger(row)">流水</el-button><el-button link :disabled="!row.can_adjust" @click="openAdjustment(row)">补发</el-button><el-button link @click="participation(row)">{{row.excluded?'恢复参与':'暂停参与'}}</el-button></td></tr><tr v-if="!users.length&&!busy&&!error"><td colspan="4">暂无匹配账号。</td></tr></tbody></table></div></el-tab-pane>
    <el-tab-pane label="积分流水" name="ledger"><form class="points-toolbar" @submit.prevent="change"><label>账号ID <el-input-number v-model="userFilter" :min="1" :precision="0" aria-label="流水账号ID"></el-input-number></label><el-button native-type="submit">查询</el-button><el-button @click="userFilter=null;change()">全部</el-button></form><div class="points-entry" v-for="row in rows" :key="row.id"><div><strong>{{row.username}} · {{row.title||pointsKind(row.kind)}}</strong><small>{{pointsTime(row.created_at)}} · 业务日期 {{row.business_day}} · 规则 v{{row.rule_id}}</small><small>{{row.reason}}<template v-if="row.actor_id"> · 管理员ID {{row.actor_id}}</template></small></div><span>{{pointsDelta(row.amount)}} <el-button v-if="row.amount>0" link @click="openAdjustment({user_id:row.user_id,username:row.username},row)">撤回</el-button></span></div><p v-if="!rows.length&&!busy&&!error">暂无流水。</p></el-tab-pane>
    <el-tab-pane label="规则设置" name="rules"><form v-if="policy&&rules" class="points-rule-form" @submit.prevent="saveRules"><p class="points-help">当前 v{{rules.current.version}}；保存常规规则于次日北京时间零点生效，不重算历史。新设置会替换尚未生效的计划。</p><label class="points-switch"><el-switch v-model="policy.enabled" aria-label="启用积分奖励"></el-switch> 启用积分奖励</label><label class="points-switch"><el-switch v-model="policy.leaderboard_enabled" aria-label="开放排行榜"></el-switch> 开放排行榜</label><div class="points-rule-fields"><label>有效阅读秒数<el-input-number v-model="policy.read_seconds" :min="10" :max="600" :precision="0" aria-label="有效阅读秒数"></el-input-number></label><template v-for="kind in ['read','upload','note']" :key="kind"><label>{{pointsKind(kind)}}每次分值<el-input-number v-model="policy[kind+'_points']" :min="0" :max="1000" :precision="0" :aria-label="pointsKind(kind)+'分值'"></el-input-number></label><label>{{pointsKind(kind)}}每日次数<el-input-number v-model="policy[kind+'_limit']" :min="0" :max="100" :precision="0" :aria-label="pointsKind(kind)+'每日次数'"></el-input-number></label></template></div><h3>等级门槛</h3><div class="points-level-editor" v-for="(item,index) in policy.levels" :key="index"><span>L{{index+1}}</span><el-input v-model="item.name" :maxlength="20" :aria-label="'等级'+(index+1)+'名称'"></el-input><el-input-number v-model="item.threshold" :min="0" :max="100000000" :disabled="index===0" :precision="0" :aria-label="'等级'+(index+1)+'积分门槛'"></el-input-number></div><label class="points-switch" v-if="!policy.enabled"><el-checkbox v-model="immediatePause">紧急暂停，立即生效</el-checkbox></label><label class="points-reason">变更原因<el-input v-model="reason" type="textarea" maxlength="500" aria-label="积分规则变更原因"></el-input></label><el-button type="primary" native-type="submit" :loading="saving" :disabled="!reason.trim()">保存规则</el-button><h3 class="points-section-title">规则历史</h3><div v-for="row in rules.history" :key="row.version" class="points-entry"><div><strong>v{{row.version}} · {{row.cancelled_at?'计划已取消':row.version===rules.current.version?'当前生效':row.version>rules.current.version?'待生效':'历史版本'}}</strong><small>{{pointsTime(row.effective_at)}} · {{row.reason}}</small></div></div></form></el-tab-pane>
    <el-tab-pane label="结算与异常" name="events"><div class="points-toolbar"><el-select v-model="eventStatus" @change="change" aria-label="积分事件状态"><el-option label="结算失败" value="failed"></el-option><el-option label="待结算" value="pending"></el-option><el-option label="未获奖励" value="ignored"></el-option><el-option label="已入账" value="awarded"></el-option></el-select></div><div v-for="row in events" :key="row.id" class="points-entry"><div><strong>{{row.title||pointsKind(row.kind)}}</strong><small>账号ID {{row.user_id||'未知'}} · {{row.business_day}} · 重试 {{row.attempts}} 次</small><small>{{row.reason||'等待结算'}}</small></div><el-button v-if="row.status==='failed'" @click="retry(row)">安排重试</el-button></div><p v-if="!events.length&&!busy&&!error">暂无该类事件。</p></el-tab-pane></el-tabs>
    <div class="points-pagination" v-if="tab!=='rules'"><el-pagination layout="prev, pager, next, total" :total="total" :page-size="20" v-model:current-page="page" @current-change="load"></el-pagination></div>
    <el-dialog v-model="adjustOpen" :title="adjustForm.original_id?'撤回原奖励':'补发荣誉积分'" width="min(520px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><p>账号：{{adjustUser?.username}}。请核对原因，不能给本人调分。</p><p v-if="adjustError" class="points-error" role="alert">{{adjustError}}</p><form class="points-rule-form" @submit.prevent="saveAdjustment"><label>调整分数<el-input-number v-model="adjustForm.amount" :min="adjustForm.original_id?-1000:1" :max="1000" :precision="0" :disabled="!!adjustForm.original_id||!!pendingAdjustment" aria-label="调整分数"></el-input-number></label><label>调整原因<el-input v-model="adjustForm.reason" type="textarea" maxlength="500" :disabled="!!pendingAdjustment" aria-label="调整原因"></el-input></label><el-button native-type="submit" type="primary" :loading="saving" :disabled="adjustForm.reason.trim().length<2">{{pendingAdjustment?'按原请求重试':'验证身份并记账'}}</el-button></form></el-dialog>
  </section>`,
};

const KnowledgePointsReader={
  data(){return {pointsReadSession:null,pointsReadGeneration:0,pointsReadClock:null,pointsReadBusy:false,pointsReadErrors:0,pointsReadInteraction:false,pointsReaderMessage:'',pointsReadListener:null,pointsVisibilityListener:null,pointsPreviouslyActive:false};},
  computed:{pointsReadableIdentity(){const doc=this.selectedDoc;if(!this.readerOpen||!doc?.id||!doc.can_read||doc.media_kind||this.readerLoading||this.readerOriginalLoading)return '';const loaded=this.readerMode==='original'?!!(this.readerBlob||this.readerUrl||this.readerSheet):!!doc.references?.some(r=>r.text);return loaded?doc.id:'';}},
  watch:{pointsReadableIdentity(value){this.stopPointsReading();if(value)this.beginPointsReading(value);}},
  mounted(){this.pointsReadListener=event=>{if(event.isTrusted&&event.target?.closest?.('.ckb-reader-columns'))this.pointsReadInteraction=true;};for(const event of ['pointerdown','keydown','wheel','scroll'])document.addEventListener(event,this.pointsReadListener,true);this.pointsVisibilityListener=()=>{if(document.hidden||!document.hasFocus())this.pointsPreviouslyActive=false;};document.addEventListener('visibilitychange',this.pointsVisibilityListener);window.addEventListener('blur',this.pointsVisibilityListener);},
  beforeUnmount(){this.stopPointsReading();for(const event of ['pointerdown','keydown','wheel','scroll'])document.removeEventListener(event,this.pointsReadListener,true);document.removeEventListener('visibilitychange',this.pointsVisibilityListener);window.removeEventListener('blur',this.pointsVisibilityListener);},
  methods:{
    stopPointsReading(){this.pointsReadGeneration++;clearInterval(this.pointsReadClock);this.pointsReadClock=null;this.pointsReadSession=null;this.pointsReadInteraction=false;this.pointsReaderMessage='';this.pointsReadBusy=false;},
    async beginPointsReading(id){const generation=this.pointsReadGeneration;try{const response=await this.apiFetch('/points/read-sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({document_id:id})});const result=await response.json();if(generation!==this.pointsReadGeneration)return;if(!response.ok||!result.eligible){this.pointsReaderMessage=result.reason||'';return;}this.pointsReadSession={id:result.session_id,sequence:0,document:id};this.pointsReadErrors=0;this.pointsPreviouslyActive=!document.hidden&&document.hasFocus();this.pointsReaderMessage='有效阅读可获积分；重复打开不重复计分。';this.pointsReadClock=setInterval(()=>this.sendPointsHeartbeat(generation),result.heartbeat_seconds*1000);}catch{/* Reading remains available when the optional points service fails. */}},
    async sendPointsHeartbeat(generation){if(this.pointsReadBusy||generation!==this.pointsReadGeneration||!this.pointsReadSession)return;this.pointsReadBusy=true;const session=this.pointsReadSession;const active=!document.hidden&&document.hasFocus()&&this.pointsReadableIdentity===session.document;const continuous=active&&this.pointsPreviouslyActive;this.pointsPreviouslyActive=active;try{const sequence=session.sequence+1;const response=await this.apiFetch('/points/read-sessions/'+encodeURIComponent(session.id)+'/heartbeat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sequence,active:continuous,interacted:this.pointsReadInteraction})});const result=await response.json();if(generation!==this.pointsReadGeneration)return;if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'积分暂不可用');session.sequence=sequence;this.pointsReadErrors=0;if(result.complete){clearInterval(this.pointsReadClock);this.pointsReadClock=null;this.pointsReaderMessage=result.awarded?'本次有效阅读 +'+result.awarded+' 分':result.reason||'本次阅读已完成计分判断。';}else this.pointsReaderMessage='有效阅读 '+result.seconds+' 秒；达到条件后自动计分。';}catch{if(generation===this.pointsReadGeneration&&++this.pointsReadErrors>=3){clearInterval(this.pointsReadClock);this.pointsReadClock=null;this.pointsReaderMessage='积分暂不可用，不影响继续阅读。';}}finally{if(generation===this.pointsReadGeneration)this.pointsReadBusy=false;}},
  },
};
